module Top;
    byte d[];
    initial begin
        d = {<< byte {32'h11223344}};
        $display("size=%0d d[0]=%h d[3]=%h", d.size(), d[0], d[3]);
    end
endmodule

module Top;
    byte q[$] = '{8'h01, 8'h02, 8'h03};
    int i;
    initial begin
        i = {>>{q}};
        $display("i=%h", i);
    end
endmodule

module Top;
    typedef logic [19:0] word_t;
    bit b[$];
    logic [127:0] w;
    word_t word;
    initial begin
        {<< bit {b}} = 20'habcde;
        $display("size=%0d b[0]=%b b[1]=%b b[19]=%b", b.size(), b[0], b[1], b[19]);
        w = {<< bit {b}};
        word = word_t'({<< bit {b}});
        $display("w=%h word=%h", w, word);
    end
endmodule

module Top;
    byte q[$];
    int i;
    initial begin
        i = {>>{q, 16'h1234}};
        $display("i=%h", i);
        i = 32'({>>{q, i >>> 16}});
        $display("i=%h", i);
    end
endmodule

module Top;
    int i_header = 12, i_len = 5, i_crc = 42;
    byte i_data[];
    int o_header, o_len, o_crc;
    byte o_data[];
    byte pkt[$];
    initial begin
        i_data = new[5];
        foreach (i_data[k]) i_data[k] = byte'(k + 1);
        pkt = {<< 8 {i_header, i_len, i_data, i_crc}};
        $display("pkt size=%0d pkt[0]=%0d pkt[4]=%0d pkt[13]=%0d", pkt.size(), pkt[0], pkt[4], pkt[13]);
        {<< 8 {o_header, o_len, o_data, o_crc}} = pkt;
        $display("header=%0d len=%0d crc=%0d size=%0d data[0]=%0d data[4]=%0d", o_header, o_len, o_crc, o_data.size(), o_data[0], o_data[4]);
    end
endmodule

module Top;
    byte o_data[] = '{1, 2, 3, 4, 5};
    initial begin
        {>> {o_data}} = {<< byte {o_data}};
        $display("size=%0d data[0]=%0d data[4]=%0d", o_data.size(), o_data[0], o_data[4]);
    end
endmodule
